import { Dashboard, DashboardDataError, type DashboardFetcher } from '@absoluteui/components/dashboard';
import { registerBuiltInWidgets } from '@absoluteui/components/dashboard/widgets';

registerBuiltInWidgets();

declare function getAccessToken(): Promise<string>;

const fetcher: DashboardFetcher = async (request, signal) => {
  const response = await fetch(request.url, {
    method: request.method,
    headers: { ...request.headers, Accept: 'application/json', Authorization: `Bearer ${await getAccessToken()}` },
    body: request.body ?? null,
    credentials: request.credentials,
    redirect: 'error',
    signal,
  });
  if (!response.ok) throw new DashboardDataError('http', 'Request failed', response.status);
  return response.json() as Promise<unknown>;
};

const host = document.createElement('div');
document.body.append(host);
Dashboard.create(host, {
  fetcher,
  allowedOrigins: ['https://api.example.com'],
  timeZone: 'Europe/Berlin',
  definition: {
    schemaVersion: 1,
    id: 'ops',
    title: 'Operations',
    variables: [{ id: 'period', kind: 'dateRange', label: 'Period', default: { preset: 'thisMonth' } }],
    dataSources: {
      tickets: { url: 'https://api.example.com/tickets/summary', params: { from: '{{period.from}}', to: '{{period.to}}' }, ttl: 60, refresh: 300 },
    },
    widgets: [{ id: 'open', type: 'kpi', title: 'Open tickets', source: 'tickets', map: { value: '/open', trend: '/daily' }, actions: { refreshable: true }, layout: { x: 0, y: 0, w: 3, h: 2 } }],
  },
});

import { Dashboard, type DashboardChangeDetail } from '@absoluteui/components/dashboard';
import { enableDashboardBuilder } from '@absoluteui/components/dashboard/builder';
import { registerBuiltInWidgets } from '@absoluteui/components/dashboard/widgets';

registerBuiltInWidgets();

const host = document.createElement('div');
document.body.append(host);
const saved = localStorage.getItem('dashboard:home');
const dashboard = Dashboard.create(host, {
  editable: true,
  definition: saved === null ? { schemaVersion: 1, id: 'home', title: 'Home', widgets: [] } : (JSON.parse(saved) as unknown),
});
enableDashboardBuilder(dashboard, {
  widgetTemplates: [{ id: 'note', label: 'Note', widget: { type: 'text', title: 'Note', options: { text: 'Write here.' } } }],
});
host.addEventListener('aui-dashboard-change', (event) => {
  const { definition } = (event as CustomEvent<DashboardChangeDetail>).detail;
  localStorage.setItem('dashboard:home', JSON.stringify(definition));
  dashboard.markSaved();
});

import { registerWidgetType, type WidgetType } from '@absoluteui/components/dashboard';

const statusWidget: WidgetType = {
  label: 'Status',
  description: 'Service status text.',
  defaultSize: { w: 3, h: 2 },
  inputs: [{ name: 'status', label: 'Status', kind: 'text', required: true }],
  checkOptions: (options) => (Object.keys(options).length === 0 ? [] : [{ path: '', expected: 'no options' }]),
  create: (context) => ({
    update: ({ inputs }) => {
      context.body.textContent = typeof inputs['status'] === 'string' ? inputs['status'] : 'Unknown';
    },
    destroy: () => {
      context.body.replaceChildren();
    },
  }),
};
registerWidgetType('acme:status', statusWidget);

import { checkDefinition, migrateDefinition } from '@absoluteui/components/dashboard';
import { definitionSchema } from '@absoluteui/components/dashboard/schema';

const candidate: unknown = JSON.parse('{"schemaVersion":1,"id":"x","title":"X","widgets":[]}');
const result = checkDefinition(migrateDefinition(candidate));
if (!result.ok) for (const issue of result.issues) console.warn(issue.path, issue.expected);
console.log(JSON.stringify(definitionSchema({ widgetTypes: ['kpi', 'text'] })).length);
